import json
import configparser
import os
from typing import Dict, Any, Optional

def load_config(config_path: str, file_format: Optional[str] = None) -> Dict[str, Any]:
    """
    读取配置文件并返回设置字典。

    支持的配置文件格式:
    - JSON (.json)
    - INI (.ini, .cfg, .conf)
    - 环境变量 (.env)

    Args:
        config_path: 配置文件的路径
        file_format: 配置文件格式（可选，如果不提供则根据文件扩展名自动判断）

    Returns:
        包含配置信息的字典

    Raises:
        FileNotFoundError: 配置文件不存在
        ValueError: 不支持的配置文件格式或文件格式错误
    """
    # 检查文件是否存在
    if not os.path.exists(config_path):
        raise FileNotFoundError(f"配置文件不存在: {config_path}")

    # 如果没有指定格式，从文件扩展名判断
    if file_format is None:
        _, ext = os.path.splitext(config_path)
        file_format = ext.lower().lstrip('.')

    # 根据格式读取配置文件
    if file_format in ['json']:
        return _load_json_config(config_path)
    elif file_format in ['ini', 'cfg', 'conf']:
        return _load_ini_config(config_path)
    elif file_format in ['env']:
        return _load_env_config(config_path)
    else:
        raise ValueError(f"不支持的配置文件格式: {file_format}。支持的格式: json, ini, cfg, conf, env")


def _load_json_config(config_path: str) -> Dict[str, Any]:
    """读取JSON格式的配置文件"""
    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
        return config
    except json.JSONDecodeError as e:
        raise ValueError(f"JSON配置文件格式错误: {e}")


def _load_ini_config(config_path: str) -> Dict[str, Any]:
    """读取INI格式的配置文件"""
    config_parser = configparser.ConfigParser()
    try:
        config_parser.read(config_path, encoding='utf-8')
    except configparser.Error as e:
        raise ValueError(f"INI配置文件格式错误: {e}")

    config = {}
    for section in config_parser.sections():
        config[section] = {}
        for key, value in config_parser[section].items():
            # 尝试将值转换为合适的数据类型
            config[section][key] = _convert_value(value)

    return config


def _load_env_config(config_path: str) -> Dict[str, Any]:
    """读取.env格式的配置文件"""
    config = {}
    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                # 跳过空行和注释
                if not line or line.startswith('#'):
                    continue
                # 解析键值对
                if '=' in line:
                    key, value = line.split('=', 1)
                    key = key.strip()
                    value = value.strip()
                    # 去除可能的引号
                    if value.startswith('"') and value.endswith('"'):
                        value = value[1:-1]
                    elif value.startswith("'") and value.endswith("'"):
                        value = value[1:-1]
                    config[key] = _convert_value(value)
    except IOError as e:
        raise ValueError(f"读取环境变量配置文件失败: {e}")

    return config


def _convert_value(value: str) -> Any:
    """
    尝试将字符串值转换为合适的数据类型。
    支持: bool, int, float, None, 字符串
    """
    # 尝试转换为布尔值
    if value.lower() in ('true', 'yes', '1'):
        return True
    elif value.lower() in ('false', 'no', '0'):
        return False

    # 尝试转换为None
    if value.lower() in ('none', 'null', 'nil'):
        return None

    # 尝试转换为整数
    try:
        return int(value)
    except ValueError:
        pass

    # 尝试转换为浮点数
    try:
        return float(value)
    except ValueError:
        pass

    # 返回原始字符串
    return value


# 使用示例
if __name__ == "__main__":
    # 示例1: 读取JSON配置文件
    try:
        json_config = load_config("config.json")
        print("JSON配置:", json_config)
    except (FileNotFoundError, ValueError) as e:
        print(f"错误: {e}")

    # 示例2: 读取INI配置文件
    try:
        ini_config = load_config("config.ini")
        print("INI配置:", ini_config)
    except (FileNotFoundError, ValueError) as e:
        print(f"错误: {e}")

    # 示例3: 读取.env配置文件
    try:
        env_config = load_config(".env")
        print("环境变量配置:", env_config)
    except (FileNotFoundError, ValueError) as e:
        print(f"错误: {e}")
